INSERT INTO public.findit_challenges(challenge_id,name,description,active) VALUES ('C013','Something Soft','Photograph something cosy or soft to touch.',true),('C014','An Unusual Mug','Find a mug with an interesting shape or design.',true),('C015','A Kitchen Utensil','Photograph a utensil used to prepare or serve food.',true),('C016','Something Wooden','Find a household item made mainly from wood.',true),('C017','A Matching Pair','Photograph two matching household objects.',true),('C018','Something With a Handle','Find an object you carry or open using a handle.',true),('C019','A Favourite Book','Photograph the cover of a book you enjoy.',true),('C020','Something Woven','Find a basket, mat or another woven item.',true),('C021','A Doorstop','Photograph something used to hold a door open.',true),('C022','Something That Tells the Time','Find a clock, watch or kitchen timer.',true),('C023','Something With a Lid','Photograph an everyday container with its lid.',true),('C024','A Fridge Magnet','Find a decorative or useful fridge magnet.',true),('C025','Something With Wheels','Photograph a household object or toy with wheels.',true),('C026','A Favourite Cushion','Find a cushion with character.',true),('C027','Something You Made','Photograph something you crafted, built or decorated.',true),('C028','A Houseplant','Photograph a plant growing indoors.',true),('C029','Something That Folds','Find an everyday item that folds away.',true),('C030','A Useful Peg or Clip','Photograph something that holds things together.',true),('C031','An Unexpected Face','Find an object that looks like it has a face.',true),('C032','Three Things That Belong Together','Arrange and photograph three related household objects.',true) ON CONFLICT (challenge_id) DO NOTHING;